                {renderHelpButton()}
                <button onClick={logout} aria-label="Log out" className="flex items-center gap-1.5 text-[12px] px-2 py-1.5 rounded-lg" style={{ color: C.inkDim }}><LogOut size={13} /><span className="hidden sm:inline">Log out</span></button>
