// ---------- Filling the catalog fast: Oga reads a photo of the price list, or pick from common items ----------
async function scanPriceListPhotos(files, context) {
  if (!AI_ACCESS_TOKEN) throw new Error('Please log in again to use Oga.');
  const images = [];
  for (const f of files.slice(0, 3)) {
    const pdf = f.type === 'application/pdf';
    if (pdf && f.size > 5 * 1024 * 1024) throw new Error('That PDF is too large (over 5 MB). Try a photo or screenshot of the price page instead.');
    const blob = pdf ? f : await resizeImageToBlob(f, 1500, 0.82);
    const data = await new Promise((resolve, reject) => { const r = new FileReader(); r.onload = () => resolve(String(r.result).split(',')[1] || ''); r.onerror = reject; r.readAsDataURL(blob); });
    images.push({ media_type: pdf ? 'application/pdf' : 'image/jpeg', data });
  }
  let response;
  try {
    response = await fetch(`${SB_URL}/functions/v1/ai`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', apikey: SB_KEY, Authorization: `Bearer ${AI_ACCESS_TOKEN}` },
      body: JSON.stringify({ task: 'scan_list', images, context }),
    });
  } catch (e) { throw new Error("Couldn't reach Oga. Check your internet connection and try again."); }
  const data = await response.json().catch(() => null);
  if (!data) {
    // No answer from the "ai" function itself: it was cut off or crashed before replying
    if ([504, 546, 408].includes(response.status)) throw new Error('Oga took too long reading this list. Try one page at a time, or a closer photo.');
    if (response.status === 413) throw new Error('That photo is too large. Try a smaller photo or one page at a time.');
    throw new Error(`Oga couldn't read the photo just now (code ${response.status}). Please try again.`);
  }
  if (!response.ok || data.error) throw new Error(data.error || `Oga couldn't read the photo just now (code ${response.status}). Please try again.`);
  return data;
}
