  y = promoText(ctx, promoLines(ctx, o.name, W - 220, 2), W / 2, y + ns * 0.35, ns * 1.08);
  if (o.tagline) { promoFont(ctx, 500, 36); ctx.fillStyle = dim; y = promoText(ctx, promoLines(ctx, o.tagline, W - 300, 2), W / 2, y + 10, 50); }
